"use strict";const t=["周日","周一","周二","周三","周四","周五","周六"];exports.currentMonth=function(){const t=new Date;return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}`},exports.dayKeyOf=function(t){return String(t||"").slice(0,10)},exports.dayLabel=function(e){const[n,r,o]=String(e).split("-").map(Number),i=new Date(n||1970,(r||1)-1,o||1).getDay();return`${r}月${o}日 ${t[i]??""}`},exports.formatAmount=function(t){const e="number"==typeof t?t:Number(t);if(!Number.isFinite(e))return"0.00";const n=e<0,r=Math.abs(e).toFixed(2),[o,i]=r.split(".");return(n?"-":"")+o.replace(/\B(?=(\d{3})+(?!\d))/g,",")+"."+i},exports.monthLabel=function(t){const[e,n]=String(t).split("-");return`${e}年${Number(n)}月`},exports.timeLabelOf=function(t){return String(t||"").slice(11,16)};
